using AcxiomCRM.Models;using AcxiomCRM.Services;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Controllers;
public class DashboardController(CrmService crm):Controller{public async Task<IActionResult> Index(DateTime? from,DateTime? to){var c=crm.Scope<Customer>();var l=crm.Scope<Lead>();var o=crm.Scope<Opportunity>();if(from.HasValue){c=c.Where(x=>x.CreatedDate>=from);l=l.Where(x=>x.CreatedDate>=from);o=o.Where(x=>x.CreatedDate>=from);}if(to.HasValue){var end=to.Value.Date.AddDays(1);c=c.Where(x=>x.CreatedDate<end);l=l.Where(x=>x.CreatedDate<end);o=o.Where(x=>x.CreatedDate<end);}var leads=await l.ToListAsync();var opp=await o.ToListAsync();var open=opp.Where(x=>x.Status=="Open").ToList();ViewBag.Cards=new Dictionary<string,string>{{"Total customers",(await c.CountAsync()).ToString()},{"Total leads",leads.Count.ToString()},{"Open leads",leads.Count(x=>x.Status is "New" or "Contacted" or "Qualified").ToString()},{"Total opportunities",opp.Count.ToString()},{"Open opportunities",open.Count.ToString()},{"Won opportunities",opp.Count(x=>x.Stage=="Won").ToString()},{"Lost opportunities",opp.Count(x=>x.Stage=="Lost").ToString()},{"Pipeline value",open.Sum(x=>x.Amount).ToString("N2")},{"Weighted pipeline",open.Sum(x=>x.Amount*x.Probability/100).ToString("N2")},{"Pending follow-ups",(await crm.Scope<FollowUp>().CountAsync(x=>x.Status=="Planned")).ToString()}};ViewBag.Leads=leads.GroupBy(x=>x.Status).ToDictionary(x=>x.Key,x=>x.Count());ViewBag.Pipeline=opp.GroupBy(x=>x.Stage).ToDictionary(x=>x.Key,x=>x.Count());ViewBag.Sales=opp.Where(x=>x.Stage=="Won"&&x.ActualCloseDate!=null).GroupBy(x=>x.ActualCloseDate!.Value.ToString("yyyy-MM")).OrderBy(x=>x.Key).ToDictionary(x=>x.Key,x=>x.Sum(y=>y.Amount));ViewBag.From=from?.ToString("yyyy-MM-dd");ViewBag.To=to?.ToString("yyyy-MM-dd");return View(await crm.Scope<FollowUp>().Where(x=>x.Status=="Planned").OrderBy(x=>x.FollowUpDate).Take(8).ToListAsync());}}
